"""English texts of the window. Keys are the Russian originals (see `tr`)."""
from types import MappingProxyType

# Problem texts are shown with a fixed second sentence.
PROBLEM_REASONS = ('Прокси выходит в интернет с другого адреса, чем вы подтвердили.', 'Прокси не отвечает.',
                   'Не удалось проверить, через какой адрес выходит прокси.', 'Прокси изменился или остановлен.',
                   'Настройки прокси не прошли проверку.', 'Сохранённый адрес выхода изменился.',
                   'Защита остановилась из-за ошибки наблюдения.', 'Защита остановилась из-за ошибки.',
                   'Защита установлена, но сейчас не работает.')
SECOND_SENTENCE = (' Напрямую Claude не выйдет — так задумано.', ' Claude will not go out directly — this is intended.')


def _with_second_sentence(texts):
    russian, english = SECOND_SENTENCE
    return MappingProxyType({**texts, **{reason + russian: texts[reason] + english for reason in PROBLEM_REASONS}})


